CODENAME="Unknown Version"
SOURCE_ID="780a73962f"
VERSION_FULL="v0.0.1 (Unknown Version) 780a73962f"

class DuckError(Exception):
    def __init__(self, text):
        self.text=text
        super().__init__(text)

def err_text(msg):
    if not msg.endswith("\n"): msg+="\n"
    return msg

# ---------------- utility ----------------

def display_width(s):
    w=0
    for ch in s:
        if unicodedata.combining(ch): continue
        if unicodedata.east_asian_width(ch) in ('W','F'): w+=2
        else: w+=1
    return w

def pad_right(s, width):
    return s + ' ' * max(0, width-display_width(s))
def pad_left(s, width):
    return ' ' * max(0, width-display_width(s)) + s
def pad_center(s, width):
    dw=display_width(s)
    if dw>=width: return s
    left=(width-dw)//2
    right=width-dw-left
    return ' '*left + s + ' '*right

def atoi_like(s):
    m=re.match(r'\s*([+-]?\d+)', str(s))
    return int(m.group(1)) if m else 0

def onoff(s):
    if s is None: return None
    t=str(s).strip().lower()
    if t in ('on','yes','true','1','y'): return True
    if t in ('off','no','false','0','n'): return False
    # sqlite-style: any nonzero / other? reference: .headers yes -> on
    return True if t not in ('',) else False

def levenshtein(a,b):
    if a==b: return 0
    la=len(a); lb=len(b)
    if la==0: return lb
    if lb==0: return la
    prev=list(range(lb+1))
    for i,ca in enumerate(a,1):
        cur=[i]
        for j,cb in enumerate(b,1):
            cur.append(min(prev[j]+1, cur[j-1]+1, prev[j-1]+(0 if ca==cb else 1)))
        prev=cur
    return prev[-1]

def jaro(s,t):
    if s==t: return 1.0
    ls=len(s); lt=len(t)
    if ls==0 or lt==0: return 0.0
    match_dist=max(ls,lt)//2-1
    if match_dist<0: match_dist=0
    s_matches=[False]*ls; t_matches=[False]*lt
    matches=0
    for i in range(ls):
        lo=max(0,i-match_dist); hi=min(lt,i+match_dist+1)
        for j in range(lo,hi):
            if not t_matches[j] and s[i]==t[j]:
                s_matches[i]=True; t_matches[j]=True; matches+=1; break
    if matches==0: return 0.0
    k=0; trans=0
    for i in range(ls):
        if s_matches[i]:
            while not t_matches[k]: k+=1
            if s[i]!=t[k]: trans+=1
            k+=1
    trans//=2
    return (matches/ls + matches/lt + (matches-trans)/matches)/3

def jaro_winkler(s,t):
    j=jaro(s,t)
    prefix=0
    for a,b in zip(s,t):
        if a==b and prefix<4: prefix+=1
        else: break
    return j + prefix*0.1*(1-j)

def did_you_mean(target, candidates, prefix='', maxn=5):
    # approximate DuckDB suggestions: rank by jaro-winkler then edit distance
    scored=[]
    for idx,c in enumerate(candidates):
        score=jaro_winkler(target.lower(), c.lower())
        dist=levenshtein(target.lower(), c.lower())
        scored.append((-score, dist, idx, c))
    scored.sort()
    out=[]
    for negscore,dist,idx,c in scored:
        if -negscore>=0.6 or dist<=2:
            out.append(c)
        if len(out)>=maxn: break
    if not out and scored:
        out=[scored[0][3]]
    return out

def format_candidates(cands, quote='"'):
    return ", ".join(f"{quote}{c}{quote}" for c in cands)

# ---------------- tokenizer ----------------
class Tok:
    __slots__=('kind','text')
    def __init__(self,kind,text): self.kind=kind; self.text=text
    def __repr__(self): return f"Tok({self.kind},{self.text!r})"
    def upper(self): return self.text.upper()

TOKEN_RE=re.compile(r"""
    (?P<ws>\s+)
  | (?P<comment>--[^\n]* | /\*.*?\*/)
  | (?P<string>'(?:[^']|'')*' | \$[A-Za-z_]*\$.*?\$\2?\$)
  | (?P<qident>"(?:[^"]|"")*")
  | (?P<number>(?:\d+\.\d*(?:[eE][+-]?\d+)?)|(?:\.\d+(?:[eE][+-]?\d+)?)|(?:\d+(?:[eE][+-]?\d+)?))
  | (?P<param>\$\d+|\?)
  | (?P<ident>[A-Za-z_\x80-\xff][A-Za-z0-9_$\x80-\xff]*)
  | (?P<op>::|:=|=>|\*\*|//|~~\*|!~~\*|~~|!~~|~ \*|!~ \*|!~|<=|>=|<>|!=|::|->>|->|<<|>>|&&|\|\||[+\-*/%<>=&|~^])
  | (?P<punct>[(),;\.\[\]{}:])
  | (?P<other>.)
""", re.X|re.S)

def tokenize(sql):
    toks=[]; i=0; n=len(sql)
    while i<n:
        m=TOKEN_RE.match(sql,i)
        if not m:
            toks.append(Tok('other', sql[i])); i+=1; continue
        kind=m.lastgroup
        text=m.group()
        # dollar quoted string handled roughly above; also e'...' handling by caller (ident e+string)
        toks.append(Tok(kind,text))
        i=m.end()
    return toks

def tok_join(toks):
    return ''.join(t.text for t in toks)

def sig_toks(toks):
    return [t for t in toks if t.kind not in ('ws','comment')]

def first_keyword(sql):
    toks=sig_toks(tokenize(sql))
    words=[]
    for t in toks[:4]:
        if t.kind=='ident': words.append(t.text.upper())
        elif t.kind=='punct' and t.text=='(':
            continue
        else: break
    return words

def split_statements(sql):
    """Split by semicolon respecting strings/comments. Returns list of (stmt_with_semi?, stmt_no_semi, start_offset)"""
    toks=tokenize(sql)
    res=[]; cur=[]; cur_start=0; pos=0
    # track char offset per token
    offsets=[]
    p=0
    for t in toks:
        offsets.append(p); p+=len(t.text)
    start_idx=0
    for idx,t in enumerate(toks):
        if t.kind=='punct' and t.text==';':
            segment=tok_join(toks[start_idx:idx+1])
            res.append((segment, tok_join(toks[start_idx:idx]), offsets[start_idx] if start_idx < len(offsets) else 0))
            start_idx=idx+1
    if start_idx < len(toks):
        segment=tok_join(toks[start_idx:])
        if segment.strip():
            res.append((segment, segment, offsets[start_idx]))
    return res

def is_complete(sql):
