        h=int(m.group(1)); mi=int(m.group(2)); sec=float(m.group(3))
        micros=int((abs(h)*3600+mi*60+sec)*1000000) * ( -1 if h<0 else 1)
        rest=s[:m.start()]+' '+s[m.end():]
    for num, unit in re.findall(r'([+-]?\d+(?:\.\d+)?)\s*(years?|yrs?|months?|mons?|weeks?|days?|hours?|hrs?|minutes?|mins?|seconds?|secs?|milliseconds?|ms|microseconds?|us)', rest, re.I):
