        if u.startswith('year') or u.startswith('yr'): months+=int(v*12)
        elif u.startswith('month') or u.startswith('mon'): months+=int(v)
        elif u.startswith('week'): days+=int(v*7)
        elif u.startswith('day'): days+=int(v)
        elif u.startswith('hour') or u.startswith('hr'): micros+=int(v*3600*1000000)
        elif u.startswith('min'): micros+=int(v*60*1000000)
        elif u.startswith('sec'): micros+=int(v*1000000)
        elif u=='ms' or u.startswith('millisec'): micros+=int(v*1000)
        elif u=='us' or u.startswith('microsec'): micros+=int(v)
    if months==0 and days==0 and micros==0:
        # maybe just number -> ?
        mm=re.match(r'^\s*([+-]?\d+)\s*$', s)
        if mm:
            # ? treat as ??? error below
            pass
    return {'months':months,'days':days,'micros':micros}

def interval_from_unit(n, unit):
    u=unit.lower().strip()
    d={'months':0,'days':0,'micros':0}
    try: v=float(n)
    except Exception: v=0
    if u.startswith('year'): d['months']=int(v*12)
    elif u.startswith('month') or u in ('mon','mons'): d['months']=int(v)
    elif u.startswith('week'): d['days']=int(v*7)
    elif u.startswith('day'): d['days']=int(v)
    elif u.startswith('hour'): d['micros']=int(v*3600000000)
    elif u.startswith('min'): d['micros']=int(v*60000000)
    elif u.startswith('sec'): d['micros']=int(v*1000000)
    elif u in ('ms','millisecond','milliseconds'): d['micros']=int(v*1000)
    elif u in ('us','microsecond','microseconds'): d['micros']=int(v)
    else: d['days']=int(v)
    return d

