    def _db_name_from_file(self, fn):
        if not fn or fn==':memory:' or fn.startswith(':memory:'):
            return 'memory'
        base=os.path.basename(fn)
        stem=os.path.splitext(base)[0]
        return stem if stem else base
    def _open(self):
        if self._is_memory():
            if self.readonly:
                raise DuckError('Catalog Error: Cannot launch in-memory database in read-only mode!\n')
            self.con=sqlite3.connect(':memory:', isolation_level=None, check_same_thread=False)
        else:
            path=self.filename_arg
            if self.readonly:
                if not os.path.exists(path):
                    raise DuckError(f'IO Error: Cannot open database "{path}" in read-only mode: database does not exist\n')
                self.con=sqlite3.connect(f'file:{path}?mode=ro', uri=True, isolation_level=None, check_same_thread=False)
            else:
                # check dir exists
                d=os.path.dirname(os.path.abspath(path))
                if not os.path.isdir(d):
                    raise DuckError(f'IO Error: Cannot open file "{path}": No such file or directory\n')
                try:
                    self.con=sqlite3.connect(path, isolation_level=None, check_same_thread=False)
                    # ensure file physically created
                    try:
                        self.con.execute('PRAGMA user_version=1')
                    except Exception:
                        pass
                except sqlite3.Error as e:
                    if 'not a database' in str(e) or 'file is encrypted' in str(e):
