        try: self.con.close()
        except Exception: pass
    def _init_meta(self):
        if self.readonly:
            return
        try:
            self.con.execute("CREATE TABLE IF NOT EXISTS _duck_meta (key TEXT PRIMARY KEY, value TEXT)")
        except Exception:
            pass
    def _load_persistent_meta(self):
        # load macros / sequences / enums / column declared types stored in _duck_meta
        self.col_declared={} # (table_lower, col_lower) -> declared string
        try:
            cur=self.con.execute("SELECT key,value FROM _duck_meta") if self._meta_exists() else None
            if cur:
                for k,v in cur.fetchall():
                    if k.startswith('macro:'):
                        try:
                            obj=json.loads(v); self.macros[k[6:]]=(obj['params'], obj['body'], obj.get('is_table',False))
                        except Exception: pass
                    elif k.startswith('seq:'):
                        try: self.sequences[k[4:]]=json.loads(v)
                        except Exception: pass
                    elif k.startswith('enum:'):
                        try: self.enums[k[5:]]=json.loads(v)
                        except Exception: pass
                    elif k.startswith('coltype:'):
                        parts=k.split(':',2)
                        if len(parts)==3: self.col_declared[(parts[1],parts[2])]=v
                    elif k.startswith('schema:'):
                        self.schemas.add(k[7:])
        except Exception:
            pass
    def _meta_exists(self):
        try:
            r=self.con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='_duck_meta'").fetchone()
            return r is not None
        except Exception:
            return False
    def _meta_set(self, key, value):
        if self.readonly: return
        try:
            if not self._meta_exists(): self._init_meta()
            self.con.execute("REPLACE INTO _duck_meta(key,value) VALUES(?,?)",(key,value))
        except Exception:
            pass
    def _meta_del_prefix(self, prefix):
        try:
            if self._meta_exists(): self.con.execute("DELETE FROM _duck_meta WHERE key LIKE ?", (prefix+'%',))
        except Exception: pass

