                if prev is None or prev.text in ('(','[',',','+','-','*','/','=','<','>') or (prev.kind=='ident' and prev.text.upper() in ('SELECT','WHERE','AND','OR','NOT','WHEN','THEN','ELSE','VALUES','SET','ON','AS','RETURNING','BETWEEN','IN','LIKE','IS')):
                    typ=t.text.upper()
                    out.extend(self._call_toks('__duck_cast',[[toks[i+1]],[Tok('string',quote_string(typ))]])); i+=2; continue
            out.append(t); i+=1
        # date +/- interval and date +/- int rewrites taking advantage of date_add/date_sub UDFs
        toks=out; out=[]; i=0
        while i<len(toks):
            t=toks[i]
            if t.text in ('+','-') and out:
                # lookahead next primary; check if it begins with __duck_interval / __duck_interval_str call or date_add etc.
                if i+1<len(toks) and toks[i+1].kind=='ident' and toks[i+1].text in ('__duck_interval','__duck_interval_str'):
                    end=self._primary_forward(toks,i+1)
                    interval_toks=toks[i+1:end]
                    start=self._primary_backward(out,len(out)); primary=out[start:]; del out[start:]
                    fn='date_add' if t.text=='+' else 'date_sub'
                    out.extend(self._call_toks(fn,[primary,interval_toks])); i=end; continue
            out.append(t); i+=1
        return out
    def _transform_operators(self, toks):
        # iteratively replace binary operators with function calls
        opmap={'/':'__duck_div','//':'__duck_idiv','%':'__duck_mod','^':'__duck_pow','**':'__duck_pow'}
        changed=True; guard=0
        while changed and guard<100:
            changed=False; guard+=1
            for idx,t in enumerate(toks):
                if t.text in opmap:
                    start=self._primary_backward(toks, idx)
                    end=self._primary_forward(toks, idx+1)
                    left=toks[start:idx]; right=toks[idx+1:end]
                    if not left or not right: continue
                    toks=toks[:start]+self._call_toks(opmap[t.text],[left,right])+toks[end:]
                    changed=True; break
