        out=[]; i=0
        while i<len(toks):
            t=toks[i]
            if t.kind=='ident' and t.text.upper()=='ILIKE' and out:
                start=self._primary_backward(out,len(out)); left=out[start:]; del out[start:]
                end=self._primary_forward(toks,i+1); right=toks[i+1:end]
                # lower(left) LIKE lower(right)
                out.append(Tok('punct','('))
                out.extend(self._call_toks('lower',[left])); out.append(Tok('ident','LIKE')); out.extend(self._call_toks('lower',[right])); out.append(Tok('punct',')'))
                i=end; continue
            if t.kind=='ident' and t.text.upper()=='SIMILAR' and i+1<len(toks) and toks[i+1].text.upper()=='TO' and out:
                start=self._primary_backward(out,len(out)); left=out[start:]; del out[start:]
                end=self._primary_forward(toks,i+2); right=toks[i+2:end]
