                start=self._primary_backward(out,len(out)); left=out[start:]
                if left:
                    del out[start:]
                    end=self._primary_forward(toks,i+1); right=toks[i+1:end]
                    if t.text=='~':
                        out.extend(self._call_toks('regexp_full_match',[left,right]))
                    elif t.text=='~~':
                        out.extend(left); out.append(Tok('ident','LIKE')); out.extend(right)
                    elif t.text=='~~*':
                        out.extend(self._call_toks('lower',[left])); out.append(Tok('ident','LIKE')); out.extend(self._call_toks('lower',[right]))
                    i=end; continue
            out.append(t); i+=1
        return out
    def _transform_keywords_funcs(self, toks):
        out=[]; i=0
