                # Here out[-2] maybe NOT
                # skip DISTINCT FROM
                if len(out)>=2 and out[-2].text.upper()=='NOT':
                    # IS NOT DISTINCT FROM -> IS : remove NOT
                    del out[-2]
                else:
                    out.append(Tok('ident','NOT'))
