                end=self._primary_forward(toks,i+3); i=end; continue
            if up=='COLLATE' and i+1<len(toks):
                coll=unquote_ident(toks[i+1].text).upper()
                if coll in ('NOCASE','BINARY','RTRIM'):
                    out.append(t); out.append(toks[i+1]); i+=2; continue
                i+=2; continue
            if t.kind=='param' and t.text.startswith('$'):
                raise DuckError('Prepared statement parameters cannot be used directly\nTo use prepared statement parameters, use PREPARE to prepare a statement, followed by EXECUTE\n')
            if t.kind=='ident':
                lu=t.text.upper()
                if lu=='CURRENT_DATE':
                    raise extension_error('current_date','icu','Scalar Function')
                if lu=='CURRENT_TIME':
                    raise extension_error('get_current_time','icu','Scalar Function', quoted_name='get_current_time')
                if lu=='LOCALTIME':
                    raise extension_error('current_localtime','icu','Scalar Function', quoted_name='current_localtime')
                if lu=='LOCALTIMESTAMP':
                    # check reference later; likely icu get_current_timestamp? treat as now
                    out.extend(self._call_toks('__now_tz',[])); i+=1; continue
                if lu=='CURRENT_TIMESTAMP':
                    # if followed by '(' it's a call - sqlite accepts? make __now_tz()
                    if i+1<len(toks) and toks[i+1].text=='(':
                        j=self._find_matching_tok(toks,i+1); out.extend(self._call_toks('__now_tz',[])); i=(j+1 if j>i else i+1); continue
                    out.extend(self._call_toks('__now_tz',[])); i+=1; continue
                # function rewrites when call
                if i+1<len(toks) and toks[i+1].text=='(':
                    if lu=='STRFTIME':
                        out.append(Tok('ident','__duck_strftime')); i+=1; continue
                    if lu=='IF':
                        out.append(Tok('ident','iif')); i+=1; continue
                    if lu=='SUBSTRING':
                        out.append(Tok('ident','substr')); i+=1; continue
                    if lu=='RANGE':
                        out.append(Tok('ident','__range_list')); i+=1; continue
                    if lu=='TODAY':
                        raise extension_error('today','icu','Scalar Function', quoted_name='today')
                    if lu=='NOW':
                        out.append(Tok('ident','now')); i+=1; continue
                    if lu=='IFNULL':
                        out.append(Tok('ident','ifnull')); i+=1; continue
                if lu=='TRUE':
                    out.append(Tok('ident','TRUE')); i+=1; continue
                if lu=='FALSE':
                    out.append(Tok('ident','FALSE')); i+=1; continue
            out.append(t); i+=1
        return out

