    # ----- generic SQL transformation -----
    def _find_matching_tok(self, toks, i):
        pairs={'(' : ')','[':']','{':'}'}
        if i>=len(toks): return -1
        o=toks[i].text; c=pairs.get(o)
        if not c: return -1
        depth=0
        for j in range(i,len(toks)):
            if toks[j].text==o: depth+=1
            elif toks[j].text==c:
                depth-=1
                if depth==0: return j
        return -1
    def _split_tok_list(self, toks, sep=','):
        parts=[]; cur=[]; depth=0
        for t in toks:
            if t.text in ('(','[','{'): depth+=1
            elif t.text in (')',']','}'): depth-=1
            if depth==0 and t.text==sep:
                parts.append(cur); cur=[]
            else:
                cur.append(t)
        if cur or toks: parts.append(cur)
        return parts
    def _primary_backward(self, toks, end_idx):
        """toks up to end_idx exclusive; return start index of primary ending at end_idx-1"""
        i=end_idx-1
        if i<0: return end_idx
        t=toks[i]
        if t.text==')':
            depth=0; j=i
            while j>=0:
                if toks[j].text==')': depth+=1
                elif toks[j].text=='(':
                    depth-=1
                    if depth==0: break
                j-=1
            start=j
            # function name
            if start-1>=0 and toks[start-1].kind in ('ident','qident'):
                start-=1
                # schema.func
                while start-2>=0 and toks[start-1].text=='.' and toks[start-2].kind in ('ident','qident'):
                    start-=2
            # CASE ... END handled separately below if start token is '(' fine
            return max(start,0)
        if t.kind=='ident' and t.text.upper()=='END':
            # find CASE
            depth=0; j=i
            while j>=0:
                if toks[j].kind=='ident' and toks[j].text.upper()=='END': depth+=1
                elif toks[j].kind=='ident' and toks[j].text.upper()=='CASE':
                    depth-=1
                    if depth==0: return j
                j-=1
            return 0
        if t.kind in ('ident','qident','string','number','param'):
            start=i
            # dotted chain
            while start-2>=0 and toks[start-1].text=='.' and toks[start-2].kind in ('ident','qident','number'):
                start-=2
            return start
        return i
    def _primary_forward(self, toks, start_idx):
        i=start_idx
        if i>=len(toks): return i
        # unary
        if toks[i].text in ('-','+','~') and toks[i].kind in ('op','punct'):
            return self._primary_forward(toks, i+1)
        if toks[i].kind=='ident' and toks[i].text.upper()=='CASE':
            depth=0; j=i
            while j<len(toks):
                if toks[j].kind=='ident' and toks[j].text.upper()=='CASE': depth+=1
                elif toks[j].kind=='ident' and toks[j].text.upper()=='END':
                    depth-=1
                    if depth==0: return j+1
                j+=1
            return len(toks)
        if toks[i].text=='(':
            j=self._find_matching_tok(toks,i)
            return j+1 if j>=0 else len(toks)
        if toks[i].kind in ('ident','qident'):
            j=i+1
            # function call
            if j<len(toks) and toks[j].text=='(':
                k=self._find_matching_tok(toks,j)
                return k+1 if k>=0 else len(toks)
            # dotted chain
            while j+1<len(toks) and toks[j].text=='.' and toks[j+1].kind in ('ident','qident'):
                j+=2
                if j<len(toks) and toks[j].text=='(':
                    k=self._find_matching_tok(toks,j); return k+1 if k>=0 else len(toks)
            return j
        return i+1
    def _parse_type_tokens(self, toks, i):
        """parse type starting i, return (type_string, next_index)"""
        if i>=len(toks): return ('VARCHAR',i)
        parts=[]; j=i
        # multi word specials
        up=lambda idx: toks[idx].text.upper() if idx<len(toks) else ''
        if up(j)=='TIMESTAMP' and up(j+1) in ('WITH','WITHOUT'):
            parts=[toks[j].text, toks[j+1].text, toks[j+2].text, toks[j+3].text] if j+3<len(toks) else [toks[j].text]
            j+=len(parts)
        elif up(j)=='DOUBLE' and up(j+1)=='PRECISION':
            parts=['DOUBLE','PRECISION']; j+=2
        elif up(j) in ('STRUCT','MAP') and j+1<len(toks) and toks[j+1].text=='(':
            k=self._find_matching_tok(toks,j+1)
            if k<0: k=len(toks)-1
            typ=tok_join(toks[j:k+1])
            return (typ,k+1)
        else:
            if j<len(toks) and toks[j].kind in ('ident','qident'):
                parts.append(unquote_ident(toks[j].text)); j+=1
            # params
            if j<len(toks) and toks[j].text=='(':
                k=self._find_matching_tok(toks,j)
                if k>=0:
                    parts.append(tok_join(toks[j:k+1])); j=k+1
        # array suffix
        suffix=''
        while j+1<len(toks) and toks[j].text=='[' and toks[j+1].text==']':
            suffix+='[]'; j+=2
        # also [n]
        if j+2<len(toks) and toks[j].text=='[' and toks[j+2].text==']':
            suffix+='[]'; j+=3
        return (' '.join(parts)+suffix, j)
    def _transform_tokens(self, toks):
        # recursive transformation pipeline on sig tokens
        toks=self._transform_special_functions(toks)
        toks=self._transform_brackets_structs_casts(toks)
        toks=self._transform_intervals_typed(toks)
        toks=self._transform_operators(toks)
        toks=self._transform_keywords_funcs(toks)
        return toks
    def _mk(self, kind, text): return Tok(kind,text)
    def _call_toks(self, fname, arg_token_lists):
        out=[Tok('ident',fname), Tok('punct','(')]
        for ai,args in enumerate(arg_token_lists):
            if ai: out.append(Tok('punct',','))
            out.extend(args)
        out.append(Tok('punct',')'))
        return out
    def _transform_special_functions(self, toks):
        # EXTRACT(part FROM expr), POSITION(a IN b), SUBSTRING(a FROM b FOR c), TRIM(...)
        out=[]; i=0
        while i<len(toks):
            if toks[i].kind=='ident' and i+1<len(toks) and toks[i+1].text=='(':
                fname=toks[i].text.upper()
                j=self._find_matching_tok(toks,i+1)
                if j>0 and fname in ('EXTRACT','POSITION','SUBSTRING','TRIM','OVERLAY'):
                    inner=toks[i+2:j]
                    if fname=='EXTRACT':
                        # find FROM top level
                        depth=0; fi=-1
                        for k,t in enumerate(inner):
                            if t.text in ('(','['): depth+=1
                            elif t.text in (')',']'): depth-=1
                            elif depth==0 and t.kind=='ident' and t.text.upper()=='FROM': fi=k; break
                        if fi>=0:
                            part=tok_join(inner[:fi]).strip()
                            expr=self._transform_tokens(inner[fi+1:])
                            out.extend(self._call_toks('date_part', [[Tok('string',quote_string(part.lower()))], expr]))
                            i=j+1; continue
                    if fname=='POSITION':
                        depth=0; ii=-1
                        for k,t in enumerate(inner):
                            if t.text in ('(','['): depth+=1
                            elif t.text in (')',']'): depth-=1
                            elif depth==0 and t.kind=='ident' and t.text.upper()=='IN': ii=k; break
                        if ii>=0:
                            needle=self._transform_tokens(inner[:ii]); hay=self._transform_tokens(inner[ii+1:])
                            out.extend(self._call_toks('strpos',[hay,needle])); i=j+1; continue
                    if fname=='SUBSTRING':
                        depth=0; fi=-1; foi=-1
                        for k,t in enumerate(inner):
                            if t.text in ('(','['): depth+=1
                            elif t.text in (')',']'): depth-=1
                            elif depth==0 and t.kind=='ident' and t.text.upper()=='FROM' and fi<0: fi=k
                            elif depth==0 and t.kind=='ident' and t.text.upper()=='FOR' and foi<0: foi=k
                        if fi>=0:
                            src=self._transform_tokens(inner[:fi])
                            start=self._transform_tokens(inner[fi+1:foi if foi>=0 else len(inner)])
                            args=[src,start]
                            if foi>=0: args.append(self._transform_tokens(inner[foi+1:]))
                            out.extend(self._call_toks('substr',args)); i=j+1; continue
                    if fname=='TRIM':
                        # TRIM([BOTH|LEADING|TRAILING [chars] FROM] source)
                        depth=0; fi=-1
                        for k,t in enumerate(inner):
                            if t.text in ('(','['): depth+=1
                            elif t.text in (')',']'): depth-=1
                            elif depth==0 and t.kind=='ident' and t.text.upper()=='FROM': fi=k; break
                        if fi>=0:
                            before=inner[:fi]
                            mode='BOTH'; chars=None
                            bi=0
                            if before and before[0].kind=='ident' and before[0].text.upper() in ('BOTH','LEADING','TRAILING'):
                                mode=before[0].text.upper(); bi=1
                            if bi<len(before): chars=self._transform_tokens(before[bi:])
                            src=self._transform_tokens(inner[fi+1:])
