                primary=out[start:]; del out[start:]
                out.extend(self._call_toks('__duck_cast',[primary,[Tok('string',quote_string(typ_str))]]))
                i=ni; continue
            out.append(t); i+=1
        return out
    def _parse_type_tokens_from_list(self, toks):
        typ, idx = self._parse_type_tokens(toks,0)
        return typ, idx
    def _transform_intervals_typed(self, toks):
        out=[]; i=0
