                        out.extend(self._call_toks('__duck_interval',[[toks[i+1]],[Tok('string',quote_string(toks[i+2].text.lower()))]])); i+=3; continue
                    out.extend(self._call_toks('__duck_interval_str',[[toks[i+1]]])); i+=2; continue
                if i+2<len(toks) and toks[i+1].kind in ('number','ident') and toks[i+2].kind=='ident':
                    unit=toks[i+2].text.upper()
                    if unit in ('YEAR','YEARS','MONTH','MONTHS','WEEK','WEEKS','DAY','DAYS','HOUR','HOURS','MINUTE','MINUTES','SECOND','SECONDS','MILLISECOND','MILLISECONDS','MICROSECOND','MICROSECONDS'):
