                        out.extend(self._call_toks('__duck_interval',[expr,[Tok('string',quote_string(unit.lower()))]])); i=j+2; continue
            if t.kind=='ident' and t.text.upper() in type_lits and i+1<len(toks) and toks[i+1].kind=='string':
