    def _clause_segments(self, toks):
        # returns list of (kind, start_idx_keyword, end) for top-level select clauses; kind canonical
        clause_starts=[]
        depth=0; i=0
        while i<len(toks):
            t=toks[i]
            if t.text in ('(','[','{'): depth+=1; i+=1; continue
            if t.text in (')',']','}'): depth-=1; i+=1; continue
            if depth==0 and t.kind=='ident':
                up=t.text.upper()
                if up in ('SELECT','FROM','WHERE','HAVING','QUALIFY','LIMIT','OFFSET','WINDOW','VALUES'):
                    clause_starts.append((up,i,i+1)); i+=1; continue
                if up in ('GROUP','ORDER') and i+1<len(toks) and toks[i+1].text.upper()=='BY':
                    clause_starts.append((up+' BY',i,i+2)); i+=2; continue
                if up in ('UNION','INTERSECT','EXCEPT'):
                    clause_starts.append(('SETOP',i,i+1)); i+=1; continue
                if up=='FETCH':
                    clause_starts.append(('FETCH',i,i+1)); i+=1; continue
            i+=1
        segs=[]
        for idx,(kind,start,content_start) in enumerate(clause_starts):
