    def _strip_alias_from_item(self, item_toks):
        # remove trailing AS alias or bare alias if identifiable (depth0)
        depth=0
        for i,t in enumerate(item_toks):
            if t.text in ('(','['): depth+=1
            elif t.text in (')',']'): depth-=1
            elif depth==0 and t.kind=='ident' and t.text.upper()=='AS':
                return item_toks[:i]
