        for s in segs:
            if s['kind']=='SETOP':
                out+=toks[s['start']:s['end']]; continue
            if s['kind']=='GROUP BY' and len(s['content'])==1 and s['content'][0].text.upper()=='ALL':
                agg_names={'count','sum','avg','min','max','string_agg','list','array_agg','median','mode','stddev','variance','bool_and','bool_or','product','approx_count_distinct'}
                group_items=[]
                for item in proj_items:
                    expr=self._strip_alias_from_item(item)
                    txt=tok_join(expr).strip().lower()
                    if not txt or txt=='*': continue
