    def _preprocess_escapes(self, sql):
        # E'...' strings -> decoded normal strings
        def repl_e(m):
            raw=m.group(1)
            # decode escapes, handling '' as '
            out=''; idx=0
            while idx<len(raw):
                c=raw[idx]
                if c=='\\' and idx+1<len(raw):
                    n=raw[idx+1]
                    mp={'n':'\n','t':'\t','r':'\r','b':'\b','f':'\f','\\':'\\',"'":"'"}
                    if n in mp: out+=mp[n]; idx+=2; continue
                    if n=='x' and idx+3<len(raw)+1:
                        try: out+=chr(int(raw[idx+2:idx+4],16)); idx+=4; continue
                        except Exception: pass
                    out+=n; idx+=2; continue
                if c=="'" and idx+1<len(raw) and raw[idx+1]=="'": out+="'"; idx+=2; continue
                out+=c; idx+=1
            return quote_string(out)
        sql=re.sub(r"(?<![A-Za-z_])[Ee]'((?:[^'\\]|''|\\.)*)'", repl_e, sql)
        # dollar quoted $$...$$ and $tag$...$tag$
        def repl_dollar(m):
            tag=m.group(1); body=m.group(2)
            return quote_string(body)
        sql=re.sub(r"\$([A-Za-z_]*)\$(.*?)\$\1\$", repl_dollar, sql, flags=re.S)
        return sql

