        def interesting(item):
            txt=tok_join(item).upper()
            if 'EXCLUDE' in txt or 'REPLACE' in txt: 
                # ensure star or columns present
                if '*' in txt or 'COLUMNS' in txt: return True
            if item and item[0].kind=='ident' and item[0].text.upper()=='COLUMNS': return True
            return False
