            probe_toks+=it
        probe_toks+=toks[sel['end']:]
        try:
            transformed=self.transform_sql(self._toks_to_sql(probe_toks), skip_star=True)
            cur=self.con.execute(f"SELECT * FROM ({transformed}) LIMIT 0")
            cols=[d[0] for d in cur.description]
        except Exception:
            return sql
