        if single:
            # position in full
            start=full.find(stmt_stripped)
            if start<0: start=0
            abspos=start+pos
            before=full[:abspos]
            line_no=before.count('\n')+1
            lines=full.splitlines()
            raw=lines[line_no-1] if line_no-1<len(lines) else stmt_stripped
            col=abspos-(before.rfind('\n')+1)
            # Duck strips leading spaces in display
            lead=len(raw)-len(raw.lstrip())
            if col>=lead: col-=lead
            line_text=raw.strip()
