                start=full.find(stmt_stripped)
                if start>0: start_line=full[:start].count('\n')+1
            line_no=start_line+line_in_stmt
            lines=stmt_stripped.splitlines() or [stmt_stripped]
            raw=lines[line_in_stmt] if line_in_stmt<len(lines) else stmt_stripped
            col=pos-(before.rfind('\n')+1)
            lead=len(raw)-len(raw.lstrip())
            if col>=lead: col-=lead
            return (line_no, raw.strip(), max(col,0))
