            t=toks[i]
            if t.text in ('(','['): depth+=1
            elif t.text in (')',']'): depth-=1
            elif depth==0:
                ut=t.text.upper()
                if ut in candidates:
                    # avoid BETWEEN's AND as AND split: callers handle between before and/or search
                    found=i
            i+=1
