    def _render_case_name(self, toks):
        # render CASE [operand] WHEN cond THEN val ELSE val END in Duck style approx
        # token segments top level
        parts=[]; cur_kind='CASE'; cur=[]
        depth=0; i=1
        segments=[]  # (kind,toks)
        operand=[]
        # gather operand until WHEN
        while i<len(toks):
            t=toks[i]
            if t.text in ('(','['): depth+=1
            elif t.text in (')',']'): depth-=1
            if depth==0 and t.kind=='ident' and t.text.upper()=='WHEN':
                break
            operand.append(t); i+=1
        out='CASE '
        if operand:
            out+=self._duck_expr_name(operand)+' '
        else:
            out+=' '
        # now i at WHEN
        while i<len(toks):
            t=toks[i]
            if t.kind=='ident' and t.text.upper()=='WHEN':
                out+='WHEN ('; i+=1
                cond=[]; depth=0
                while i<len(toks):
                    tt=toks[i]
                    if tt.text in ('(','['): depth+=1
                    elif tt.text in (')',']'): depth-=1
                    if depth==0 and tt.kind=='ident' and tt.text.upper()=='THEN': break
                    cond.append(tt); i+=1
                out+='('+self._duck_expr_name(cond).lstrip('(') if False else '('+self._duck_expr_name(cond)+')'
                # Duck observed: WHEN ((1 > 0)) -> our expr is (1 > 0), wrap in one extra ()
                # Above produced ((1 > 0)) if cond rendering has outer parens - need exactly: 'WHEN (' + rendering + ')'
                # We already appended 'WHEN (' and then '('+render+')' -> that's WHEN ((render)) double. Fix by rebuilding:
                # (leave as is: rendering for comparison is '(1 > 0)', we appended '('+render+')' = '((1 > 0))', plus prefix 'WHEN (' gives 'WHEN (((...' triple. So correct it:)
                # Remove duplication: rebuild out ending
                # Simpler: strip last constructed chunk and redo - hack: out currently ends with ... ; replace 'WHEN (((' if occurs
                out=out.replace('WHEN (((','WHEN ((')
                out+=') THEN ('; i+=1
                val=[]; depth=0
                while i<len(toks):
                    tt=toks[i]
                    if tt.text in ('(','['): depth+=1
                    elif tt.text in (')',']'): depth-=1
                    if depth==0 and tt.kind=='ident' and tt.text.upper() in ('WHEN','ELSE','END'): break
                    val.append(tt); i+=1
                out+=self._duck_expr_name(val)+') '
                continue
            if t.kind=='ident' and t.text.upper()=='ELSE':
                out+='ELSE '; i+=1
                val=[]; depth=0
                while i<len(toks):
                    tt=toks[i]
                    if tt.text in ('(','['): depth+=1
                    elif tt.text in (')',']'): depth-=1
                    if depth==0 and tt.kind=='ident' and tt.text.upper()=='END': break
                    val.append(tt); i+=1
                out+=self._duck_expr_name(val)+' '
                continue
            if t.kind=='ident' and t.text.upper()=='END':
                out+='END'; i+=1; break
            i+=1
        return out.strip()
    def _render_sql_words(self, toks):
        out=''
        for i,t in enumerate(toks):
            txt=t.text
            if t.kind=='ident' and txt.upper() in ('SELECT','FROM','WHERE','GROUP','BY','ORDER','LIMIT','AS','AND','OR','NOT','OVER','PARTITION','CASE','WHEN','THEN','ELSE','END','UNION','ALL','DISTINCT'):
                txt=txt.upper()
            if out and txt not in (')',',','.','(') and not out.endswith(('(','.')):
                out+=' '
            if txt==',' : out+=','
            else: out+=txt
        out=out.replace('( ','(').replace(' )',')').replace(' ,',',')
        out=re.sub(r',(?=[^\s])', ', ', out)
        return out

