            res=self._execute_generic(rest, context)
            outcols=[('column_name','varchar'),('column_type','varchar'),('null','varchar'),('key','varchar'),('default','varchar'),('extra','varchar')]
            rows=[]
            fake=[]
            for name,disp in res.columns:
                can=display_to_sql_type(disp).upper()
                rows.append((name, can, 'YES', None, None, None))
                fake.append({'name':name,'declared':can,'display':disp,'notnull':False,'pk':False,'default':None})
            return Result(columns=outcols, rows=rows, is_special_describe={'title':'Describe','columns':fake})
        tbl=rest.strip()
        if self.find_table(tbl):
            return self._describe_result_for_table(tbl)
        cand=[t['name'] for t in self.list_tables()]+PG_TABLE_NAMES
        sug=did_you_mean(tbl,cand)
        base=f'Catalog Error: Table with name {tbl} does not exist!\n'
        if sug: base+=f'Did you mean "{sug[0]}"?\n'
        raise DuckError(self._with_line(base, context, tbl))
    def _execute_summarize(self, sql, context):
        rest=re.sub(r'(?is)^SUMMARIZE\s+', '', sql).strip()
        if rest.upper().startswith('TABLE '): rest=rest[6:].strip()
        words=first_keyword(rest)
        if words and words[0] in ('SELECT','WITH','FROM','VALUES') or rest.startswith('('):
            res=self._execute_generic(rest, context)
        else:
            if not self.find_table(rest):
                raise DuckError(f'Catalog Error: Table with name {rest} does not exist!\n')
            res=self._execute_generic(f"SELECT * FROM {rest}", context)
        outcols=[('column_name','varchar'),('column_type','varchar'),('min','varchar'),('max','varchar'),('approx_unique','int64'),('avg','double'),('std','double'),('q25','double'),('q50','double'),('q75','double'),('count','int64'),('null_percentage','varchar')]
        rows=[]
        n=len(res.rows)
        for ci,(name,disp) in enumerate(res.columns):
            vals=[r[ci] for r in res.rows if r[ci] is not None]
            mn=min(vals, key=lambda x: str(x)) if vals else None
            mx=max(vals, key=lambda x: str(x)) if vals else None
            # numeric stats
            avg=None; std=None; q25=q50=q75=None
            nums=[]
            for v in vals:
                try: nums.append(float(v))
                except Exception: pass
            if nums and disp not in ('varchar','boolean'):
                avg=sum(nums)/len(nums)
                if len(nums)>1:
                    m=avg; std=math.sqrt(sum((x-m)**2 for x in nums)/(len(nums)-1))
                s=sorted(nums)
                def quant(q):
                    pos=q*(len(s)-1); lo=math.floor(pos); hi=math.ceil(pos)
                    if lo==hi: return s[int(pos)]
                    return s[lo]+(s[hi]-s[lo])*(pos-lo)
                q25,q50,q75=quant(0.25),quant(0.5),quant(0.75)
            nullpct=None if n==0 else (f"{(n-len(vals))/n*100:.2f}%" if False else ((n-len(vals))/n))
            # Reference null_percentage format unknown; probe later. In list mode for non-null likely 0.00% ? We'll store string with %
            if n>0: nullpct=f"{(n-len(vals))/n*100:.2f}%"
            rows.append((name, display_to_sql_type(disp).upper(), any_value_to_duck_string(mn) if mn is not None else None, any_value_to_duck_string(mx) if mx is not None else None, len(set(vals)), avg, std, q25,q50,q75, n, nullpct))
        return Result(columns=outcols, rows=rows)

