            tables=self.list_tables()
            names=sorted([t['name'] for t in tables if t['type']=='table'])
            # Duck show tables includes views? includes tables only? probe later; include views? It lists tables (not views?) We'll include tables only
            return Result(columns=[('name','varchar')], rows=[(n,) for n in names])
