            cols=[('database','varchar'),('schema','varchar'),('name','varchar'),('column_names','varchar[]'),('column_types','varchar[]'),('temporary','boolean')]
            rows=[]
            for t in sorted(self.list_tables(), key=lambda x: x['name'].lower()):
                if t['type']!='table': continue
                cc=self.table_columns(t['name'])
                rows.append((t['database'],t['schema'],t['name'],tag_list([c['name'] for c in cc]),tag_list([declared_canonical(c['declared']) for c in cc]), t['temporary']))
            return Result(columns=cols, rows=rows)
        if low.rstrip(';')=='databases':
            cols=[('database_name','varchar')]
            return Result(columns=cols, rows=[(a['name'],) for a in self.attached])
        # SHOW table_name -> describe
        tbl=rest.strip().rstrip(';')
        # if tbl contains spaces, maybe SHOW CREATE etc unsupported parser handled in ref as parser; let table lookup fail for first word? For SHOW CREATE TABLE ref gives parser at create
        if re.match(r'(?i)create\b', tbl):
