        rows=[]
        for c in cols:
            is_null='NO' if (c['notnull'] or c['pk']) else 'YES'
            key='PRI' if c['pk'] else None
            dflt=c['default']
            rows.append((c['name'], declared_canonical(c['declared']), is_null, key, dflt, None))
