            out.append(line(title))
            out.append('│'+pad_center('─'*20,w-2)+'│' if False else '│'+pad_center('────────────────────',w-2)+'│')
            for l in lines: out.append(line(l))
            out.append(line(''))
            out.append(line('~1 row'))
            out.append('└'+'─'*((w-2)//2)+'┬'+'─'*(w-2-(w-2)//2-1)+'┘')
            return '\n'.join(out)
        header='\n┌─────────────────────────────┐\n│┌───────────────────────────┐│\n││       Physical Plan       ││\n│└───────────────────────────┘│\n└─────────────────────────────┘\n'
        proj=box('PROJECTION', proj_texts or ['*'])
        if from_table:
            scan_title='SEQ_SCAN'
            # simple scan box
            w=29
            child='┌'+'─'*13+'┴'+'─'*13+'┐\n'+'│'+pad_center(scan_title,27)+'│\n'+'│'+pad_center(from_table,27)+'│\n'+'└'+'─'*27+'┘\n'
