        if name not in self.prepared:
            raise DuckError(f'Catalog Error: Prepared statement with name {name} does not exist!\n')
        prep=self.prepared[name]
        arg_str=m.group(2) or ''
        args=split_top_level(arg_str,',') if arg_str.strip() else []
        def repl(mm):
            idx=int(mm.group(1))-1
            return '('+args[idx]+')' if 0<=idx<len(args) else 'NULL'
        exec_sql=re.sub(r'\$(\d+)', repl, prep)
        res=self.execute(exec_sql, context)
        # override names based on prepared sql
        if isinstance(res,Result) and res.columns:
            items,_,_=self._select_items_from_sql(prep)
            if items and len(items)==len(res.columns):
                newcols=[]
                for (oldname,typ),it in zip(res.columns, items):
                    alias,expr=self._alias_of_item(it)
                    nm=alias or self._duck_expr_name(expr) or oldname
                    # duck_expr_name for param tokens: _find etc may return token; ensure $ preserved - if nm missing $ and '$' in tok_join(expr), use simple render
                    if '$' in tok_join(expr) and '$' not in nm:
                        nm='('+tok_join(expr).replace('+',' + ').replace('-',' - ')+')'
                    newcols.append((nm,typ))
                res.columns=newcols
        return res

