        if 'TYPE' in words:
            m=re.search(r'(?is)TYPE\s+(?:IF\s+EXISTS\s+)?"?([\w]+)"?',sql)
            if m: self.enums.pop(m.group(1).lower(),None)
            return Result([],[],changes=0)
        if 'SCHEMA' in words:
            m=re.search(r'(?is)SCHEMA\s+(?:IF\s+EXISTS\s+)?"?([\w]+)"?',sql)
            if m: self.schemas.discard(m.group(1).lower())
            return Result([],[],changes=0)
