        return res
    def _execute_alter(self, sql, context):
        # remove IF EXISTS after ALTER TABLE for sqlite (not supported)
        sql2=re.sub(r'(?is)ALTER\s+TABLE\s+IF\s+EXISTS\s+','ALTER TABLE ',sql)
        # Add column IF NOT EXISTS
        m=re.search(r'(?is)ALTER\s+TABLE\s+((?:"[^"]+"|[\w]+)(?:\.[\w\"]+)*)\s+ADD\s+(?:COLUMN\s+)?IF\s+NOT\s+EXISTS\s+([A-Za-z_][\w]*)', sql2)
        if m:
            tbl=unquote_ident(m.group(1).split('.')[-1]); col=m.group(2)
            if any(c['name'].lower()==col.lower() for c in self.table_columns(tbl)):
                return Result([],[],changes=0)
            sql2=re.sub(r'(?is)ADD\s+(?:COLUMN\s+)?IF\s+NOT\s+EXISTS\s+','ADD COLUMN ',sql2)
        # Drop column IF EXISTS
        m=re.search(r'(?is)ALTER\s+TABLE\s+((?:"[^"]+"|[\w]+)(?:\.[\w\"]+)*)\s+DROP\s+(?:COLUMN\s+)?IF\s+EXISTS\s+([A-Za-z_][\w]*)', sql2)
        if m:
            tbl=unquote_ident(m.group(1).split('.')[-1]); col=m.group(2)
            if not any(c['name'].lower()==col.lower() for c in self.table_columns(tbl)):
                return Result([],[],changes=0)
            sql2=re.sub(r'(?is)DROP\s+(?:COLUMN\s+)?IF\s+EXISTS\s+','DROP COLUMN ',sql2)
        # alter column type: ALTER TABLE t ALTER COLUMN c TYPE new / SET DATA TYPE
        m=re.match(r'(?is)ALTER\s+TABLE\s+((?:"[^"]+"|[\w]+)(?:\.[\w\"]+)*)\s+ALTER\s+(?:COLUMN\s+)?([A-Za-z_][\w]*)\s+(?:SET\s+DATA\s+)?TYPE\s+(.+)$', sql2)
        if m:
            tbl=unquote_ident(m.group(1).split('.')[-1]); col=m.group(2); newtype=m.group(3).strip()
            self.col_declared[(tbl.lower(),col.lower())]=newtype; self._meta_set(f'coltype:{tbl.lower()}:{col.lower()}',newtype)
            try: self._normalize_table(tbl)
            except Exception as e:
                if isinstance(e,DuckError): raise e
            return Result([],[],changes=0)
        # record added column type
        res=self._execute_generic(sql2, context)
        m=re.search(r'(?is)ALTER\s+TABLE\s+((?:"[^"]+"|[\w]+)(?:\.[\w\"]+)*)\s+ADD\s+(?:COLUMN\s+)?"?([A-Za-z_][\w]*)"?\s+([A-Za-z_][\w]*(?:\s*\([^)]*\))?(?:\[\])?)', sql2)
        if m:
            tbl=unquote_ident(m.group(1).split('.')[-1]); col=m.group(2); typ=m.group(3)
            self.col_declared[(tbl.lower(),col.lower())]=typ; self._meta_set(f'coltype:{tbl.lower()}:{col.lower()}',typ)
        return res

