def _shell_execute_sql_text(self, text, is_command=False, echo_done=False):
    if text is None: return True
    if is_command and text.startswith('.'):
        return self.handle_dot(text.strip())
    stmts=[s for s in split_statements(text) if s[1].strip()]
    if not stmts: return True
    if self.echo and not echo_done:
        self.write(text if text.endswith('\n') else text+'\n', once_ok=False)
    for idx,(full,stmt,off) in enumerate(stmts):
        if self.should_exit: return False
        start_t=time.perf_counter(); cpu_start=time.process_time()
        res_start=time.time()
        error_before=self.exit_code
        try:
            res=self.db.execute(stmt, {'stmt':stmt,'full':text,'index':idx,'count':len(stmts)})
        except DuckError as e:
            sys.stderr.write(err_text(e.text)); sys.stderr.flush(); self.exit_code=1
            return False
        except Exception as e:
            sys.stderr.write(f'Error: {e}\n'); sys.stderr.flush(); self.exit_code=1
            return False
        if res is not None:
            self.render(res)
            if self.changes and res.changes is not None:
                self.total_changes+=res.changes
                self.write(f'changes: {res.changes:3d}   total_changes: {self.total_changes}\n', once_ok=False)
        if self.timer:
            real=time.perf_counter()-start_t; user=time.process_time()-cpu_start; sys_t=max(0.0,real-user)
            self.write(f'Run Time (s): real {real:.3f} user {user:.6f} sys {sys_t:.6f}\n', once_ok=False)
    return True
