    def _transform_agg_order(self,toks):
        out=[]; i=0
        agg_names={'string_agg','group_concat','list','array_agg','sum','count','avg','min','max','median','quantile','first','last','string_agg'}
        while i<len(toks):
            if toks[i].kind=='ident' and toks[i].text.lower() in agg_names and i+1<len(toks) and toks[i+1].text=='(':
                j=self._find_matching_tok(toks,i+1)
                if j>i:
                    inner=toks[i+2:j]; depth=0; oi=-1
                    for k,t in enumerate(inner):
                        if t.text in ('(','['): depth+=1
                        elif t.text in (')',']'): depth-=1
                        elif depth==0 and t.kind=='ident' and t.text.upper()=='ORDER' and k+1<len(inner) and inner[k+1].text.upper()=='BY': oi=k; break
                    if oi>=0:
                        pre=inner[:oi]; order_toks=inner[oi+2:]
                        desc=False
                        if order_toks and order_toks[-1].text.upper() in ('DESC','ASC'):
                            desc=order_toks[-1].text.upper()=='DESC'; order_toks=order_toks[:-1]
                        # drop NULLS FIRST/LAST
                        if len(order_toks)>=2 and order_toks[-2].text.upper()=='NULLS': order_toks=order_toks[:-2]
                        fname=toks[i].text.lower(); args=self._split_tok_list(pre,',')
                        order_items=self._split_tok_list(order_toks,',')
                        if len(order_items)==1 and order_items[0]:
                            key=self._transform_tokens(order_items[0]); flag=[Tok('number','1' if desc else '0')]
                            if fname in ('string_agg','group_concat'):
                                if len(args)==1: args.append([Tok('string',"','")])
                                newargs=[self._transform_tokens(a) for a in args[:2]]+[key,flag]
                                out.extend(self._call_toks('__string_agg_ord',newargs)); i=j+1; continue
                            if fname in ('list','array_agg'):
                                newargs=[self._transform_tokens(args[0]),key,flag]
                                out.extend(self._call_toks('__list_agg_ord',newargs)); i=j+1; continue
                        # strip order by for other aggregates
                        out.extend([toks[i],toks[i+1]]); out.extend(self._transform_tokens(pre)); out.append(Tok('punct',')')); i=j+1; continue
            out.append(toks[i]); i+=1
        return out
