    def _execute_insert_by_name(self, sql, context):
        m=re.match(r'(?is)INSERT\s+(?:OR\s+\w+\s+)?INTO\s+((?:"[^"]+"|[\w]+)(?:\.[\w\"]+)*)\s+BY\s+NAME\s+(.+)$', sql, re.S)
        if not m: return NOT_HANDLED
        tbl=unquote_ident(m.group(1).split('.')[-1]); query=m.group(2).strip()
        if query.startswith('(') and find_matching(query,0)==len(query)-1:
            query=query[1:-1]
        if not self.find_table(tbl):
            sug=did_you_mean(tbl,[t['name'] for t in self.list_tables()]+PG_TABLE_NAMES)
            raise DuckError(f'Catalog Error: Table with name {tbl} does not exist!\n'+(f'Did you mean "{sug[0]}"?\n' if sug else ''))
        res=self._execute_generic(query, context)
        target=self.table_columns(tbl); tmap={c['name'].lower():c for c in target}
        cols=[]
        for name,typ in res.columns:
            if name.lower() not in tmap:
                raise DuckError(f'Binder Error: Column {name} does not exist in table {tbl}\n')
            cols.append(tmap[name.lower()]['name'])
        vals=[]
        for r in res.rows:
            row=[]
            for v,cn in zip(r,cols):
                decl=tmap[cn.lower()]['declared']
                if v is not None:
                    try: v=duck_cast_value(v,decl)
                    except DuckError: raise
                row.append(1 if isinstance(v,bool) and v else 0 if isinstance(v,bool) else v)
            vals.append(tuple(row))
        physical=self.find_table(tbl).get('physical',tbl)
        self.con.executemany(f"INSERT INTO {quote_ident(physical)} ({', '.join(quote_ident(c) for c in cols)}) VALUES ({', '.join(['?']*len(cols))})", vals)
        return Result([],[],changes=len(vals))
    def _handle_delete_using(self, sql):
        toks=sig_toks(tokenize(sql))
        if not toks or toks[0].text.upper()!='DELETE': return sql
        depths=self._tok_depths(toks); ui=None
        for i,t in enumerate(toks):
            if depths[i]==0 and t.kind=='ident' and t.text.upper()=='USING': ui=i; break
        if ui is None: return sql
        # target between FROM and USING
        fi=next((i for i,t in enumerate(toks) if t.text.upper()=='FROM'),None)
        if fi is None: return sql
        target=toks[fi+1:ui]; uend=self._join_source_forward(toks,ui+1); using=toks[ui+1:uend]; rest=toks[uend:]
        where=[]; returning=[]
        if rest and rest[0].text.upper()=='WHERE':
            ri=next((i for i,t in enumerate(rest) if t.text.upper()=='RETURNING'),len(rest)); where=rest[1:ri]; returning=rest[ri:]
        elif rest and rest[0].text.upper()=='RETURNING': returning=rest
        out=[Tok('ident','DELETE'),Tok('ident','FROM')]+target+[Tok('ident','WHERE'),Tok('ident','EXISTS'),Tok('punct','('),Tok('ident','SELECT'),Tok('number','1'),Tok('ident','FROM')]+using
        if where: out+=[Tok('ident','WHERE')]+where
        out.append(Tok('punct',')')); out+=returning
        return self._toks_to_sql(out)
