def _pq_schema_tree(schema):
    it=iter(schema)
    def parse(elem):
        node={'elem':elem,'children':[]}
        for _ in range(int(elem.get(5,0) or 0)):
            try: child=next(it)
            except StopIteration: break
            node['children'].append(parse(child))
        return node
    try: root_elem=next(it)
    except StopIteration: return {'elem':{},'children':[]}
    return parse(root_elem)
