                for ci,colch in enumerate(rg.get(1,[])):
                    colmeta=colch.get(3,{}); elem=leaves_with_path[ci][0]['elem'] if ci<len(leaves_with_path) else {}
                    colvals.append(_pq_read_column(blob,colmeta,elem))
                n=max([len(x) for x in colvals]+[0])
                for ri in range(n): all_rows.append(tuple(colvals[ci][ri] if ri<len(colvals[ci]) else None for ci in range(len(colvals))))
            else:
                streams={}
                for ci,colch in enumerate(rg.get(1,[])):
                    if ci>=len(leaves_with_path): break
                    leaf_node,path=leaves_with_path[ci]; maxd,maxr=_pq_def_rep(path)
                    streams[id(leaf_node)]=_pq_read_column(blob,colch.get(3,{}),leaf_node['elem'],max_def_override=maxd,max_rep=maxr,return_triples=True)
